'use strict';

var Int64 = require( '@stdlib/number/int64/ctor' );
var toWords = require( './../lib' );

var a = new Int64( 4294967296 );
var w = toWords( a );
console.log( w );
// => [ 1, 0 ]

a = new Int64( 10000000000 );
w = toWords( a );
console.log( w );
// => [ 2, 1410065408 ]

a = new Int64( -1 );
w = toWords( a );
console.log( w );
// => [ 4294967295, 4294967295 ]

a = new Int64( -1000000000000 );
w = toWords( a );
console.log( w );
// => [ 4294967063, 727379968 ]

a = Int64.of( 12, 34 );
w = toWords( a );
console.log( w );
// => [ 12, 34 ]
